@namespace sv_9e441df5de354ca8a5c10f083b3b1d9b.Components.Pages.Chat

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public required string ChannelName { get; set; }
    [Parameter] public string ChannelDescription { get; set; } = string.Empty;
    [Parameter, EditorRequired] public required List<Services.Message> Messages { get; set; }
    [Parameter] public List<Services.ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<MessageItem.ReactionEvent> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;

    private int GetReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading more messages
        // This is handled via JS interop in a real app; here we use a simplified approach
        await OnLoadMore.InvokeAsync();
    }
}

@namespace sv_9e441df5de354ca8a5c10f083b3b1d9b.Components.Pages.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p class="message-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSend="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Services.Message? RootMessage { get; set; }
    [Parameter] public List<Services.Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hr ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@page "/chat"
@namespace sv_9e441df5de354ca8a5c10f083b3b1d9b.Components.Pages.Chat
@rendermode InteractiveServer
@using sv_9e441df5de354ca8a5c10f083b3b1d9b.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(threadOpen ? "thread-visible" : "")">
        <MessageArea ChannelName="@selectedChannelName"
                     ChannelDescription="@selectedChannelDescription"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingMore="isLoadingMore"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private List<Message> threadReplies = [];
    private Message? threadRootMessage;

    private int selectedChannelId;
    private string selectedChannelName = string.Empty;
    private string selectedChannelDescription = string.Empty;
    private bool threadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannelId = channel.Id;
        selectedChannelName = channel.Name;
        selectedChannelDescription = channel.Description;
        messageSkip = 0;
        threadOpen = false;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;

        // Build thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new ThreadSummary(m.Id, messages.Count(r => r.ReplyToId == m.Id), DateTime.UtcNow))
            .Where(t => t.ReplyCount > 0)
            .ToList();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update the unread count locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
        }

        isLoadingMore = false;
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary count
        var existing = threadSummaries.FindIndex(t => t.RootMessageId == threadRootMessage.Id);
        if (existing >= 0)
        {
            threadSummaries[existing] = threadSummaries[existing] with { ReplyCount = threadReplies.Count, LastReplyAt = DateTime.UtcNow };
        }
        else
        {
            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, threadReplies.Count, DateTime.UtcNow));
        }
    }

    private async Task HandleReaction(MessageItem.ReactionEvent reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Update local state
        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existingReaction = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existingReaction is not null)
            {
                existingReaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }
}

